import './TagList.css';

interface TagListProps {
  tags: string[];
}

export function TagList({ tags }: TagListProps): JSX.Element {
  return (
    <ul role="list" className="tag-list">
      {tags.map((tag) => (
        <li key={tag} className="tag-list-item">
          <span className="tag-pill">{tag}</span>
        </li>
      ))}
    </ul>
  );
}
